mapper.insert:
INSERT INTO ainer_identity_activation_grant (
    id, provisioning_request_id, tenant_id, subject_id,
    secret_hash, status, attempt_count, max_attempts,
    created_at, expires_at, last_attempt_at, consumed_at
) VALUES (
    #{id}, #{provisioningRequestId}, #{tenantId}, #{subjectId},
    #{secretHash}, #{status}, #{attemptCount}, #{maxAttempts},
    #{createdAt}, #{expiresAt}, #{lastAttemptAt}, #{consumedAt}
)

mapper.update:
UPDATE ainer_identity_activation_grant
SET status = 'EXPIRED',
    last_attempt_at = #{lastAttemptAt}
WHERE id = #{grantId}
  AND status = 'ACTIVE'
  AND attempt_count = #{expectedAttemptCount}

UPDATE ainer_identity_activation_grant
SET status = 'EXPIRED',
    last_attempt_at = #{lastAttemptAt}
WHERE provisioning_request_id = #{requestId}
  AND status = 'ACTIVE'

UPDATE ainer_identity_activation_grant
SET status = 'CANCELLED',
    last_attempt_at = #{cancelledAt}
WHERE provisioning_request_id = #{requestId}
  AND status = 'ACTIVE'

UPDATE ainer_identity_activation_grant
SET status = 'CONSUMED',
    consumed_at = #{consumedAt},
    last_attempt_at = #{consumedAt}
WHERE id = #{grantId}
  AND status = 'ACTIVE'
  AND attempt_count = #{expectedAttemptCount}
  AND expires_at > #{consumedAt}

